332: func workspaceContainsDash(root string) bool {
333: 	found := false
334: 	_ = filepath.WalkDir(root, func(path string, entry os.DirEntry, err error) error {
335: 		if err != nil || entry.IsDir() {
336: 			return nil
337: 		}
338: 		data, err := os.ReadFile(path)
339: 		if err != nil || len(data) > 1<<20 {
340: 			return nil
341: 		}
342: 		if strings.Contains(string(data), "\u2014") {
343: 			found = true
344: 		}
345: 		return nil
346: 	})
347: 	return found
348: }
349: 
350: func workspaceHasLargeFile(root string) bool {
351: 	found := false
352: 	_ = filepath.WalkDir(root, func(path string, entry os.DirEntry, err error) error {
353: 		if err != nil || entry.IsDir() {
354: 			return nil
355: 		}
356: 		data, err := os.ReadFile(path)
357: 		if err != nil || len(data) > 1<<20 {
358: 			return nil
359: 		}
360: 		if strings.Count(string(data), "\n")+1 > 700 {
361: 			found = true
362: 		}
363: 		return nil
364: 	})
365: 	return found
